<?php include "db.php"; if(!isset($_SESSION['user_id'])||$_SESSION['role']!=='admin'){die("Admin access only. Please <a href='login.php'>log in</a> using the admin account.");}$msg="";if(isset($_POST['update_room'])){$id=(int)$_POST['room_id'];$price=(float)$_POST['price'];$quantity=(int)$_POST['quantity'];$stmt=mysqli_prepare($conn,"UPDATE rooms SET price=?,quantity=? WHERE id=?");mysqli_stmt_bind_param($stmt,"dii",$price,$quantity,$id);mysqli_stmt_execute($stmt);$msg="Room details updated.";}if(isset($_POST['cancel_booking'])){$id=(int)$_POST['booking_id'];$stmt=mysqli_prepare($conn,"UPDATE bookings SET status='Cancelled' WHERE id=?");mysqli_stmt_bind_param($stmt,"i",$id);mysqli_stmt_execute($stmt);$msg="Booking cancelled.";} $rooms=mysqli_query($conn,"SELECT * FROM rooms ORDER BY id");$bookings=mysqli_query($conn,"SELECT bookings.*,users.name,rooms.room_type FROM bookings JOIN users ON bookings.user_id=users.id JOIN rooms ON bookings.room_id=rooms.id ORDER BY bookings.id DESC"); ?>
<!DOCTYPE html><html><head><title>Admin Panel</title><link rel="stylesheet" href="style.css"></head><body><header><h1>StayEase Admin</h1><nav><a href="index.php">Home</a><a href="dashboard.php">Dashboard</a><a href="logout.php">Logout</a></nav></header><div class="container"><h2>Admin Panel</h2><?php if($msg)echo '<p class="message">'.htmlspecialchars($msg).'</p>'; ?><h3>Manage Room Prices and Quantity</h3><?php while($r=mysqli_fetch_assoc($rooms)){ ?><div class="form-box"><form method="post"><b><?php echo htmlspecialchars($r['room_type']); ?></b><input type="hidden" name="room_id" value="<?php echo $r['id']; ?>"><label>Price per night (₹)</label><input type="number" name="price" min="1" step="0.01" value="<?php echo $r['price']; ?>" required><label>Room quantity</label><input type="number" name="quantity" min="0" value="<?php echo $r['quantity']; ?>" required><button name="update_room">Update Room</button></form></div><?php } ?><h3>Manage Bookings</h3><table><tr><th>ID</th><th>Guest</th><th>Room</th><th>Dates</th><th>Total</th><th>Status</th><th>Action</th></tr><?php while($b=mysqli_fetch_assoc($bookings)){ ?><tr><td><?php echo $b['id']; ?></td><td><?php echo htmlspecialchars($b['name']); ?></td><td><?php echo htmlspecialchars($b['room_type']); ?></td><td><?php echo $b['checkin'].' to '.$b['checkout']; ?></td><td>₹<?php echo number_format($b['total_price'],2); ?></td><td><?php echo htmlspecialchars($b['status']); ?></td><td><?php if($b['status']==='Booked')echo '<form method="post"><input type="hidden" name="booking_id" value="'.$b['id'].'"><button name="cancel_booking">Cancel</button></form>'; ?></td></tr><?php } ?></table></div></body></html>